1	#include "LlmClient.hpp"
2	
3	#include <chrono>
4	#include <utility>
5	
6	#include "httplib.h"
7	#include "json.hpp"
8	
9	namespace llm_npc {
10	
11	using nlohmann::json;
12	
13	LlmClient::LlmClient(LlmConfig config) : config_(std::move(config)) {
14	    worker_ = std::thread(&LlmClient::workerLoop, this);
15	}
16	
17	LlmClient::~LlmClient() {
18	    stop_.store(true);
19	    requestCv_.notify_all();
20	    if (worker_.joinable()) worker_.join();
21	}
22	
23	std::uint64_t LlmClient::submit(std::string systemPrompt,
24	                                std::vector<ChatTurn> history,
25	                                std::string userMessage) {
26	    ChatRequest req;
27	    req.id = nextId_.fetch_add(1);
28	    req.systemPrompt = std::move(systemPrompt);
29	    req.history = std::move(history);
30	    req.userMessage = std::move(userMessage);
31	
32	    {
33	        std::lock_guard<std::mutex> lock(requestMutex_);
34	        requests_.push(std::move(req));
35	    }
36	    requestCv_.notify_one();
37	    return req.id;
38	}
39	
40	std::vector<ChatReply> LlmClient::drainReplies() {
41	    std::vector<ChatReply> out;
42	    std::lock_guard<std::mutex> lock(replyMutex_);
43	    out.swap(replies_);
44	    return out;
45	}
46	
47	void LlmClient::workerLoop() {
48	    while (true) {
49	        ChatRequest req;
50	        {
51	            std::unique_lock<std::mutex> lock(requestMutex_);
52	            requestCv_.wait(lock, [this] { return stop_.load() || !requests_.empty(); });
53	            if (stop_.load() && requests_.empty()) return;
54	            req = std::move(requests_.front());
55	            requests_.pop();
56	        }
57	
58	        inFlight_.store(true);
59	        ChatReply reply = processOne(req);
60	        {
61	            std::lock_guard<std::mutex> lock(replyMutex_);
62	            replies_.push_back(std::move(reply));
63	        }
64	        // Drop the flag only after the reply is queued so UI can poll busy()
65	        // without seeing a brief idle window before the reply lands.
66	        inFlight_.store(false);
67	    }
68	}
69	
70	ChatReply LlmClient::processOne(const ChatRequest& req) {
71	    ChatReply reply;
72	    reply.id = req.id;
73	
74	    // Build Ollama /api/chat body. Ollama is OpenAI-style: messages[] with
75	    // role/content, optional options for temperature, stream=false for a
76	    // single non-streamed response.
77	    json messages = json::array();
78	    if (!req.systemPrompt.empty()) {
79	        messages.push_back({{"role", "system"}, {"content", req.systemPrompt}});
80	    }
81	    for (const auto& turn : req.history) {
82	        messages.push_back({{"role", turn.role}, {"content", turn.content}});
83	    }
84	    messages.push_back({{"role", "user"}, {"content", req.userMessage}});
85	
86	    json body = {
87	        {"model", config_.model},
88	        {"messages", messages},
89	        {"stream", false},
90	        {"options", {{"temperature", config_.temperature}}},
91	    };
92	    std::string bodyStr = body.dump();
93	
94	    httplib::Client cli(config_.host, config_.port);
95	    cli.set_read_timeout(config_.requestTimeoutSeconds, 0);
96	    cli.set_write_timeout(config_.requestTimeoutSeconds, 0);
97	    cli.set_connection_timeout(5, 0);
98	
99	    auto res = cli.Post("/api/chat", bodyStr, "application/json");
100	    if (!res) {
101	        reply.errorMessage = "could not reach Ollama at " + config_.host + ":" +
102	                             std::to_string(config_.port);
103	        return reply;
104	    }
105	    if (res->status != 200) {
106	        reply.errorMessage = "Ollama returned HTTP " + std::to_string(res->status) +
107	                             ": " + res->body;
108	        return reply;
109	    }
110	
111	    try {
112	        json parsed = json::parse(res->body);
113	        // Ollama replies with { "message": { "role": ..., "content": ... }, ... }
114	        if (parsed.contains("message") && parsed["message"].contains("content")) {
115	            reply.content = parsed["message"]["content"].get<std::string>();
116	            reply.ok = true;
117	        } else if (parsed.contains("error")) {
