3	#include <algorithm>
4	#include <utility>
5	
6	namespace llm_npc {
7	
8	namespace {
9	constexpr float kPadding = 16.f;
10	constexpr float kInputHeight = 48.f;
11	constexpr float kLineHeight = 22.f;
12	constexpr unsigned kFontSize = 16;
13	
14	sf::Color colorFor(TranscriptLine::Kind k) {
15	    switch (k) {
16	        case TranscriptLine::Kind::Player: return sf::Color(180, 220, 255);
17	        case TranscriptLine::Kind::Npc:    return sf::Color(255, 230, 180);
18	        case TranscriptLine::Kind::System: return sf::Color(180, 180, 180);
19	    }
20	    return sf::Color::White;
21	}
22	
23	// Wrap a string to roughly `maxChars` per line. Word-aware: never splits a
24	// word unless the word itself exceeds maxChars. Crude but enough for chat.
25	std::vector<std::string> wrap(const std::string& s, std::size_t maxChars) {
26	    std::vector<std::string> out;
27	    std::string current;
28	    std::string word;
29	    auto flushWord = [&]() {
30	        if (word.empty()) return;
31	        if (current.empty()) {
32	            current = word;
33	        } else if (current.size() + 1 + word.size() <= maxChars) {
34	            current += ' ';
35	            current += word;
36	        } else {
37	            out.push_back(current);
38	            current = word;
39	        }
40	        word.clear();
41	    };
42	    for (char c : s) {
43	        if (c == '\n') {
44	            flushWord();
45	            out.push_back(current);
46	            current.clear();
47	        } else if (c == ' ' || c == '\t') {
48	            flushWord();
49	        } else {
50	            word += c;
51	            if (word.size() > maxChars) {
52	                // Oversized word: hard-break.
53	                if (!current.empty()) {
54	                    out.push_back(current);
55	                    current.clear();
56	                }
57	                out.push_back(word);
58	                word.clear();
59	            }
60	        }
61	    }
62	    flushWord();
63	    if (!current.empty()) out.push_back(current);
64	    return out;
65	}
66	}  // namespace
67	
68	DialogUI::DialogUI(const sf::Font& font) : font_(font) {}
69	
70	std::string DialogUI::handleEvent(const sf::Event& event) {
71	    if (!inputEnabled_) return {};
72	
73	    if (event.type == sf::Event::TextEntered) {
74	        const auto unicode = event.text.unicode;
75	        if (unicode == 8) {  // backspace
76	            if (!input_.empty()) input_.pop_back();
77	        } else if (unicode == 13 || unicode == 10) {  // enter
78	            // Handled in KeyPressed below to avoid double-fire on some platforms.
79	        } else if (unicode >= 32 && unicode < 127) {
80	            input_ += static_cast<char>(unicode);
81	        }
82	        return {};
83	    }
84	
85	    if (event.type == sf::Event::KeyPressed &&
86	        (event.key.code == sf::Keyboard::Enter || event.key.code == sf::Keyboard::Return)) {
87	        if (input_.empty()) return {};
88	        std::string submitted = std::move(input_);
89	        input_.clear();
90	        return submitted;
91	    }
92	    return {};
93	}
94	
95	void DialogUI::appendLine(TranscriptLine line) { pushLine(std::move(line)); }
96	
97	void DialogUI::pushLine(TranscriptLine line) {
98	    transcript_.push_back(std::move(line));
99	    while (transcript_.size() > kMaxTranscriptLines) transcript_.pop_front();
100	}
101	
102	void DialogUI::setThinking(bool thinking, const std::string& speaker) {
103	    thinking_ = thinking;
104	    thinkingSpeaker_ = speaker;
105	}
106	
107	void DialogUI::setInputEnabled(bool enabled) { inputEnabled_ = enabled; }
108	
109	void DialogUI::render(sf::RenderTarget& target) const {
110	    const sf::Vector2u sz = target.getSize();
111	    const float w = static_cast<float>(sz.x);
112	    const float h = static_cast<float>(sz.y);
113	
114	    const float transcriptBottom = h - kInputHeight - kPadding;
115	    const std::size_t wrapChars = std::max<std::size_t>(20, static_cast<std::size_t>((w - 2 * kPadding) / 9.0f));
116	
117	    // Collect wrapped, colored lines from newest backward until we run out of
118	    // vertical space. Then render them in chronological order.
119	    struct RenderedLine { std::string text; sf::Color color; };
120	    std::vector<RenderedLine> rendered;
121	    float used = 0.f;
122	    const float available = transcriptBottom - kPadding;
123	
124	    if (thinking_) {
125	        std::string indicator = "... " + (thinkingSpeaker_.empty() ? std::string("(thinking)")
126	                                                                    : thinkingSpeaker_ + " is thinking...");
127	        rendered.push_back({indicator, sf::Color(140, 140, 140)});
128	        used += kLineHeight;
129	    }
130	
131	    for (auto it = transcript_.rbegin(); it != transcript_.rend(); ++it) {
132	        const auto& line = *it;
133	        std::string prefix = line.speaker.empty() ? "" : line.speaker + ": ";
134	        auto wrapped = wrap(prefix + line.text, wrapChars);
135	        // Push in reverse so chronological order is preserved once we reverse the whole vector.
136	        for (auto wi = wrapped.rbegin(); wi != wrapped.rend(); ++wi) {
137	            if (used + kLineHeight > available) break;
138	            rendered.push_back({*wi, colorFor(line.kind)});
139	            used += kLineHeight;
140	        }
141	        if (used + kLineHeight > available) break;
142	    }
143	
144	    std::reverse(rendered.begin(), rendered.end());
145	
146	    float y = transcriptBottom - static_cast<float>(rendered.size()) * kLineHeight;
147	    for (const auto& rl : rendered) {
148	        sf::Text t(rl.text, font_, kFontSize);
149	        t.setFillColor(rl.color);
150	        t.setPosition(kPadding, y);
151	        target.draw(t);
152	        y += kLineHeight;
153	    }
154	
155	    // Input box.
156	    sf::RectangleShape box(sf::Vector2f(w - 2 * kPadding, kInputHeight));
157	    box.setPosition(kPadding, h - kInputHeight - kPadding * 0.5f);
158	    box.setFillColor(sf::Color(30, 30, 36));
159	    box.setOutlineColor(inputEnabled_ ? sf::Color(120, 160, 220) : sf::Color(70, 70, 70));
160	    box.setOutlineThickness(2.f);
161	    target.draw(box);
162	
163	    sf::Text prompt(std::string("> ") + input_ + (inputEnabled_ ? "_" : ""), font_, kFontSize);
164	    prompt.setFillColor(inputEnabled_ ? sf::Color::White : sf::Color(120, 120, 120));
165	    prompt.setPosition(kPadding + 10.f, h - kInputHeight - kPadding * 0.5f + 12.f);
166	    target.draw(prompt);
167	}
168	
169	}  // namespace llm_npc
