void drawEnemy(const Enemy& enemy) {
    glPushMatrix();
    glTranslatef(enemy.pos.x, enemy.pos.y, enemy.pos.z);
    glRotatef(-enemy.headingDeg, 0.0f, 1.0f, 0.0f);

    if (enemy.type == EnemyType::Sprinter) {
        drawTexturedCylinder(Vec3{0.0f, 0.0f, 0.0f}, 2.0f, 2.6f, 20, gTextures.enemy, sf::Color(255, 150, 120));
        drawTexturedBox(Vec3{0.0f, 3.8f, 0.0f}, 1.2f, 1.0f, 1.2f, gTextures.enemy, sf::Color(255, 220, 190), 1.0f);
        drawTexturedBox(Vec3{0.0f, 0.8f, 2.4f}, 0.5f, 0.3f, 1.0f, gTextures.metal, sf::Color::White, 1.0f);
    } else if (enemy.type == EnemyType::Tank) {
        drawTexturedCylinder(Vec3{0.0f, 0.0f, 0.0f}, 3.0f, 3.8f, 20, gTextures.enemy, sf::Color(170, 70, 70));
        drawTexturedBox(Vec3{0.0f, 5.2f, 0.0f}, 1.9f, 1.4f, 1.6f, gTextures.enemy, sf::Color(255, 220, 190), 1.0f);
        drawTexturedBox(Vec3{0.0f, 1.0f, 3.1f}, 0.9f, 0.45f, 1.5f, gTextures.metal, sf::Color(255, 210, 140), 1.0f);
    } else {
        drawTexturedCylinder(Vec3{0.0f, 0.0f, 0.0f}, 2.4f, 3.0f, 20, gTextures.enemy, sf::Color::White);
        drawTexturedBox(Vec3{0.0f, 4.4f, 0.0f}, 1.5f, 1.2f, 1.4f, gTextures.enemy, sf::Color(255, 220, 190), 1.0f);
