#pragma once

#include <cstdint>
#include <string>

namespace llm_npc {

// Tracks the player's conversation with one NPC at a time, including the
// in-flight LLM request and the partially streamed reply. Pure state machine
// (no SFML, no networking) so the app layer stays a thin shell:
//
//   Roaming --open()--> Talking --submitted()--> WaitingReply
//   WaitingReply --deltaArrived()--> Streaming
//   WaitingReply/Streaming --replyArrived()--> Talking
//   any state --close()--> Roaming
class DialogueSession {
   public:
    enum class State { Roaming, Talking, WaitingReply, Streaming };

    // Begin talking to the NPC at `npcIndex` (index into the world's roster).
    void open(int npcIndex);

    // Leave the conversation and return to roaming. Any in-flight request is
    // forgotten by the session; the app routes its late reply to the NPC's
    // history separately.
    void close();

    // True in every state except Roaming.
    bool isOpen() const { return state_ != State::Roaming; }

    State state() const { return state_; }

    // Roster index of the NPC being talked to; -1 while roaming.
    int npcIndex() const { return npcIndex_; }

    // The player submitted a line that became LLM request `requestId`.
    void submitted(std::uint64_t requestId);

    // A streamed text fragment arrived. Accumulates and returns true only
    // when `id` matches the in-flight request of this open session.
    bool deltaArrived(std::uint64_t id, const std::string& text);

    // The final reply arrived. Returns true when it closes out this
    // session's in-flight request; streaming text is cleared either way the
    // request resolves (success or error).
    bool replyArrived(std::uint64_t id, bool ok);

    // Partial reply text accumulated while Streaming.
    const std::string& streamingText() const { return streamingText_; }

    // The id of the request awaiting a reply; 0 when none.
    std::uint64_t pendingRequestId() const { return pendingId_; }

   private:
    State state_ = State::Roaming;
    int npcIndex_ = -1;
    std::uint64_t pendingId_ = 0;
    std::string streamingText_;
};

}  // namespace llm_npc

#pragma once

#include <filesystem>
#include <string>
#include <vector>

#include "Math.hpp"
#include "Persona.hpp"

namespace llm_npc {

// A persona plus its placement in the city, loaded from personas/<id>.persona.
struct LoadedPersona {
    std::string id;         // filename stem, e.g. "baker"
    Persona persona;        // identity rendered into the system prompt
    Vec3 position;          // world position on the ground plane (y = 0)
    float facingDeg = 0.f;  // initial facing, degrees around +y (0 = +z)
    std::string spotId;     // landmark tag, e.g. "bakery" or "park"
};

// Result of parsing one persona definition.
struct PersonaParseResult {
    bool ok = false;
    LoadedPersona value;
    std::string error;  // human-readable reason when !ok
};

// Parses one persona definition. Format: a key=value header, then an optional
// '---' line followed by free-form extra system-prompt directives:
//
//   name = Marge Holloway        (required)
//   role = bakery owner
//   traits = warm, gossipy       (comma-separated)
//   style = 1-3 short sentences
//   knowledge = Knows the neighborhood; nothing of world news.
//   spot = bakery
//   position = -40, 28           (x, z world coordinates)
//   facing = 180                 (degrees)
//   ---
//   Everything after the --- line is passed to the model verbatim.
//
// Header lines are taken literally (no comment stripping) so persona text can
// contain any character except a leading 'key =' shape.
PersonaParseResult parsePersonaText(const std::string& text, const std::string& id);

// Parses a single .persona file; the persona id is the filename stem.
PersonaParseResult parsePersonaFile(const std::filesystem::path& path);

// Loads every *.persona file in dir, sorted by filename for a deterministic
// roster order. Files that fail to parse are skipped; their error messages
// are appended to `errors` when it is non-null.
std::vector<LoadedPersona> loadAllPersonas(const std::filesystem::path& dir,
                                           std::vector<std::string>* errors = nullptr);

}  // namespace llm_npc

